+    <script>
+      const quizData = [
+        {
+          id: "question-1",
+          prompt: "Which of these are statically typed programming languages?",
+          helpText: "Select every language that usually checks types before the program runs.",
+          options: [
+            { id: "q1-rust", label: "Rust", correct: true },
+            { id: "q1-python", label: "Python", correct: false },
+            { id: "q1-java", label: "Java", correct: true },
+            { id: "q1-javascript", label: "JavaScript", correct: false }
+          ]
+        },
+        {
+          id: "question-2",
+          prompt: "Which languages are commonly used for web browsers without extra plugins?",
+          options: [
+            { id: "q2-javascript", label: "JavaScript", correct: true },
+            { id: "q2-html", label: "HTML", correct: true },
+            { id: "q2-cpp", label: "C++", correct: false },
+            { id: "q2-css", label: "CSS", correct: true }
+          ]
+        },
+        {
+          id: "question-3",
+          prompt: "Which of these are popular query or data-focused languages?",
+          options: [
+            { id: "q3-sql", label: "SQL", correct: true },
+            { id: "q3-graphql", label: "GraphQL", correct: true },
+            { id: "q3-ruby", label: "Ruby", correct: false },
+            { id: "q3-json", label: "JSON", correct: false }
+          ]
+        }
+      ];
+
+      function createElement(tagName, attributes = {}, children = []) {
+        const element = document.createElement(tagName);
+
+        Object.entries(attributes).forEach(([key, value]) => {
+          if (value === null || value === undefined || value === false) {
+            return;
+          }
+
+          if (key === "className") {
+            element.className = value;
+            return;
+          }
+
+          if (key === "text") {
+            element.textContent = value;
+            return;
+          }
+
+          if (key === "html") {
+            element.innerHTML = value;
+            return;
+          }
+
+          if (key.startsWith("on") && typeof value === "function") {
+            element.addEventListener(key.slice(2).toLowerCase(), value);
+            return;
+          }
+
+          if (value === true) {
+            element.setAttribute(key, "");
+            return;
+          }
+
+          element.setAttribute(key, value);
+        });
+
+        children.flat().forEach((child) => {
+          if (child === null || child === undefined) {
+            return;
+          }
+
+          element.append(child);
+        });
+
+        return element;
+      }
+
+      function Option({ questionId, option }) {
+        const input = createElement("input", {
+          id: option.id,
+          type: "checkbox",
+          name: questionId,
+          value: option.label
+        });
+
+        const label = createElement("label", {
+          for: option.id,
+          text: option.label
+        });
+
+        return createElement("div", { className: "choice" }, [input, label]);
+      }
+
+      function QuizQuestion({ question, index }) {
+        const helpId = question.helpText ? question.id + "-help" : null;
+        const errorId = question.id + "-error";
+        const describedBy = [helpId, errorId].filter(Boolean).join(" ");
+
+        const legend = createElement("legend", {}, [
+          createElement("span", {
+            className: "question-index",
+            text: "Question " + (index + 1)
+          }),
+          document.createTextNode(question.prompt)
+        ]);
+
+        const help = question.helpText
