    <script>
      const quizData = [
        {
          id: "question-1",
          prompt: "Which of these are statically typed programming languages?",
          helpText: "Select every language that usually checks types before the program runs.",
          options: [
            { id: "q1-rust", label: "Rust", correct: true },
            { id: "q1-python", label: "Python", correct: false },
            { id: "q1-java", label: "Java", correct: true },
            { id: "q1-javascript", label: "JavaScript", correct: false }
          ]
        },
        {
          id: "question-2",
          prompt: "Which languages are commonly used for web browsers without extra plugins?",
          options: [
            { id: "q2-javascript", label: "JavaScript", correct: true },
            { id: "q2-html", label: "HTML", correct: true },
            { id: "q2-cpp", label: "C++", correct: false },
            { id: "q2-css", label: "CSS", correct: true }
          ]
        },
        {
          id: "question-3",
          prompt: "Which of these are popular query or data-focused languages?",
          options: [
            { id: "q3-sql", label: "SQL", correct: true },
            { id: "q3-graphql", label: "GraphQL", correct: true },
            { id: "q3-ruby", label: "Ruby", correct: false },
            { id: "q3-json", label: "JSON", correct: false }
          ]
        }
      ];

      function createElement(tagName, attributes = {}, children = []) {
        const element = document.createElement(tagName);

        Object.entries(attributes).forEach(([key, value]) => {
          if (value === null || value === undefined || value === false) {
            return;
          }

          if (key === "className") {
            element.className = value;
            return;
          }

          if (key === "text") {
            element.textContent = value;
            return;
          }

          if (key === "html") {
            element.innerHTML = value;
            return;
          }

          if (key.startsWith("on") && typeof value === "function") {
            element.addEventListener(key.slice(2).toLowerCase(), value);
            return;
          }

          if (value === true) {
            element.setAttribute(key, "");
            return;
          }

          element.setAttribute(key, value);
        });

        children.flat().forEach((child) => {
          if (child === null || child === undefined) {
            return;
          }

          element.append(child);
        });

        return element;
      }

      function Option({ questionId, option }) {
        const input = createElement("input", {
          id: option.id,
          type: "checkbox",
          name: questionId,
          value: option.label
        });

        const label = createElement("label", {
          for: option.id,
          text: option.label
        });

        return createElement("div", { className: "choice" }, [input, label]);
      }

      function QuizQuestion({ question, index }) {
        const helpId = question.helpText ? question.id + "-help" : null;
        const errorId = question.id + "-error";
        const describedBy = [helpId, errorId].filter(Boolean).join(" ");

        const legend = createElement("legend", {}, [
          createElement("span", {
            className: "question-index",
            text: "Question " + (index + 1)
          }),
          document.createTextNode(question.prompt)
        ]);

        const help = question.helpText
          ? createElement("p", {
              id: helpId,
              className: "field-help",
              text: question.helpText
            })
          : null;

        const error = createElement("p", {
          id: errorId,
          className: "field-error",
          hidden: true,
          text: "Error: Select at least one answer for this question."
        });

        const options = createElement(
          "div",
          { className: "option-list" },
          question.options.map((option) => Option({ questionId: question.id, option }))
        );

        const fieldset = createElement("fieldset", {
          "data-question-id": question.id,
          "aria-describedby": describedBy
        }, [legend, help, error, options]);

        return createElement("div", { className: "form-field" }, [fieldset]);
      }

      function Hero() {
        return createElement("section", { className: "hero" }, [
          createElement("h1", { text: "Computer Languages Quiz" }),
          createElement("p", {
            text: "Each question allows multiple answers. Choose every option you think fits before submitting."
          })
        ]);
      }

      function QuizForm() {
        const form = createElement("form", { className: "quiz-form", novalidate: true });

        quizData.forEach((question, index) => {
          form.append(QuizQuestion({ question, index }));
        });

        const status = createElement("p", {
          id: "quiz-status",
          className: "status-message",
          role: "status",
          "aria-live": "polite"
        });

        const button = createElement("button", {
          type: "submit",
          text: "Submit quiz"
        });

        form.append(
          createElement("div", { className: "actions" }, [button, status])
        );

        form.addEventListener("submit", handleSubmit);
        form.addEventListener("change", clearQuestionError);

        return form;
      }

      function App() {
        return [Hero(), QuizForm()];
      }

      function clearQuestionError(event) {
        const target = event.target;
        if (!(target instanceof HTMLInputElement) || target.type !== "checkbox") {
          return;
        }

        const fieldset = target.closest("fieldset");
        if (!fieldset) {
          return;
        }

        const error = fieldset.querySelector(".field-error");
        const wrapper = fieldset.closest(".form-field");

        if (error) {
          error.hidden = true;
        }

        if (wrapper) {
          wrapper.classList.remove("has-error");
        }
      }

      function handleSubmit(event) {
        event.preventDefault();

        const form = event.currentTarget;
        const status = form.querySelector("#quiz-status");
        const results = [];
        let firstInvalidInput = null;
        let allAnswered = true;
        let score = 0;

        quizData.forEach((question) => {
          const fieldset = form.querySelector('[data-question-id="' + question.id + '"]');
          const wrapper = fieldset.closest(".form-field");
          const checkedInputs = Array.from(
            fieldset.querySelectorAll('input[type="checkbox"]:checked')
          );
          const error = fieldset.querySelector(".field-error");

          if (checkedInputs.length === 0) {
            allAnswered = false;
            error.hidden = false;
            wrapper.classList.add("has-error");
            if (!firstInvalidInput) {
              firstInvalidInput = fieldset.querySelector('input[type="checkbox"]');
            }
            return;
          }

          error.hidden = true;
          wrapper.classList.remove("has-error");

          const selectedLabels = checkedInputs.map((input) => input.value);
          const correctLabels = question.options
            .filter((option) => option.correct)
            .map((option) => option.label);

          const isCorrect =
            selectedLabels.length === correctLabels.length &&
            selectedLabels.every((label) => correctLabels.includes(label));

          if (isCorrect) {
            score += 1;
          }

          results.push("Q" + (results.length + 1) + ": " + selectedLabels.join(", "));
        });

        if (!allAnswered) {
          status.dataset.tone = "error";
          status.textContent = "Please answer every question before submitting.";
          if (firstInvalidInput) {
            firstInvalidInput.focus();
          }
          return;
        }

        status.dataset.tone = "success";
        status.textContent =
          "You scored " +
          score +
          " out of " +
          quizData.length +
          ". " +
          results.join(" | ");
      }

      function render(root, component) {
        component.flat().forEach((node) => root.append(node));
      }

      render(document.getElementById("maincontent"), App());
    </script>
  </body>
