       html {
         color-scheme: dark;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--color-text);
         background:
           radial-gradient(circle at top, #1a2850 0%, transparent 32%),
           linear-gradient(180deg, #090d1a 0%, var(--color-bg) 100%);
       }

       a {
         color: var(--color-link);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: var(--color-text);
         color: #000;
         transform: translateY(-200%);
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       .skip-link:focus {
         transform: translateY(0);
         z-index: 10;
       }

       .page-shell {
         width: min(100%, 56rem);
         margin: 0 auto;
         padding: 2rem 1rem 4rem;
       }

       .hero {
         margin-bottom: 1.5rem;
         padding: 1.5rem;
         border: 1px solid var(--color-border);
         border-radius: 1.25rem;
         background: linear-gradient(180deg, rgba(27, 36, 66, 0.96), rgba(17, 24, 45, 0.96));
         box-shadow: 0 18px 48px rgba(0, 0, 0, 0.35);
