       button {
         border: 1px solid #9cb7ff;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         font: inherit;
         font-weight: 700;
         color: #07101f;
         background: linear-gradient(180deg, #c7d7ff, #8fb0ff);
         cursor: pointer;
