       .status-message[data-tone="success"] {
         color: var(--color-success);
       }

       .status-message[data-tone="error"] {
         color: var(--color-danger);
       }

       :focus-visible {
         outline: 3px solid var(--color-focus);
         outline-offset: 3px;
       }

       @media (max-width: 40rem) {
         .page-shell {
           padding-inline: 0.75rem;
         }

         .hero,
         .form-field {
           padding: 1rem;
         }
       }

       @media (forced-colors: active) {
         :root {
           --color-bg: Canvas;
           --color-panel: Canvas;
           --color-panel-strong: Canvas;
           --color-text: CanvasText;
           --color-muted-text: CanvasText;
           --color-link: LinkText;
           --color-border: ButtonBorder;
           --color-focus: Highlight;
           --color-danger: HighlightText;
           --color-success: HighlightText;
           --color-accent: Highlight;
         }

         .hero,
         .form-field,
         .choice,
         button {
           box-shadow: none;
         }

         button {
           color: ButtonText;
           background: ButtonFace;
         }
       }
